INSERT INTO public.collections VALUES (1, 'classic', 'کلاسیک', 'فرم‌هایی که پیر نمی‌شوند', 'کالکشن کلاسیک کیف‌شاپ بر پایه‌ی فرم‌های ماندگار ساخته شده است: کیف دستی مستطیلی، توت ساده و بندهای کوتاه. این قطعه‌ها برای محیط کار، قرارهای رسمی و استفاده‌ی روزمره طراحی شده‌اند و در طول سال‌ها فرم خود را حفظ می‌کنند.', '/images/handbag-white.jpg', '#c8a96a', 1);
INSERT INTO public.collections VALUES (2, 'urban', 'شهری', 'سبک، کاربردی، همیشه همراه', 'کالکشن شهری برای روزهای شلوغ تهران و سفرهای کوتاه است: کیف دوشی، کیف اداری اسلیم و توت سفر. جیب‌های هوشمند و وزن کم، مهم‌ترین ویژگی این مجموعه است.', '/images/crossbody.jpg', '#8a9a7b', 2);
INSERT INTO public.collections VALUES (3, 'atelier', 'آتلیه', 'دست‌دوز، شماره‌دار، محدود', 'آتلیه، قلب کیف‌شاپ است. قطعه‌هایی که با دوخت دست، نخ موم‌اندود و بدون چسب صنعتی ساخته می‌شوند. هر عدد شماره‌ی سریال دارد و تا ۱۰ سال تعمیر می‌شود.', '/images/tote-hand.jpg', '#a8563b', 3);
INSERT INTO public.collections VALUES (4, 'evening', 'مجلسی', 'برای شب‌های خاص', 'کالکشن مجلسی شامل کلاچ‌ها و کیف‌های دستی کروک‌امباس با یراق طلایی است. تولید محدود و بسته‌بندی هدیه، این مجموعه را به گزینه‌ی مناسب هدیه تبدیل می‌کند.', '/images/clutch.jpg', '#b08d57', 4);


