INSERT INTO public.faqs VALUES (1, 'کیف چرم کیف‌شاپ اصل است؟', 'بله. همه‌ی کیف‌ها از چرم طبیعی گاوی یا بزی دباغی‌شده ساخته می‌شوند و مهر آتلیه، کارت اصالت و شماره سریال دارند. در صورت درخواست، برگه آزمون چرم و مشخصات دباغی نیز ارائه می‌شود.', 'اصالت', 1, true);
INSERT INTO public.faqs VALUES (2, 'هزینه و زمان ارسال کیف چرم چقدر است؟', 'ارسال با پست پیشتاز و تیپاکس انجام می‌شود. سفارش‌های بالای ۳ میلیون تومان ارسال رایگان دارند؛ در غیر این صورت هزینه ارسال ۶۵ هزار تومان است. زمان تحویل در تهران ۲۴ تا ۴۸ ساعت و در شهرستان‌ها ۲ تا ۴ روز کاری است.', 'ارسال', 2, true);
INSERT INTO public.faqs VALUES (3, 'اگر سایز یا رنگ کیف مناسب نبود چه کنم؟', 'تا ۷ روز پس از دریافت، اگر کیف استفاده نشده و پلمب آن باز نشده باشد، تعویض رنگ یا مدل انجام می‌شود. برای کیف‌های سفارشی و حکاکی‌شده، تعویض فقط در صورت ایراد تولیدی ممکن است.', 'تعویض', 3, true);
INSERT INTO public.faqs VALUES (4, 'گارانتی کیف‌شاپ چه چیزهایی را پوشش می‌دهد؟', 'گارانتی ۵ ساله کیف‌شاپ دوخت، یراق و درز‌های بدنه را پوشش می‌دهد. فرسایش طبیعی چرم، پارگی ناشی از ضربه و تماس با مواد شیمیایی مشمول گارانتی نیست. تعمیر کیف‌های آتلیه تا ۱۰ سال انجام می‌شود.', 'گارانتی', 4, true);
INSERT INTO public.faqs VALUES (5, 'چطور سایز مناسب کیف دستی را انتخاب کنم؟', 'برای استفاده روزمره، عرض ۲۶ تا ۳۲ سانتی‌متر کافی است. اگر لپ‌تاپ ۱۴ یا ۱۵ اینچ حمل می‌کنید، توت یا کیف اداری با عرض حداقل ۳۶ سانتی‌متر انتخاب کنید. جدول کامل سایز و وزن در صفحه راهنمای سایزبندی آمده است.', 'راهنمای خرید', 5, true);
INSERT INTO public.faqs VALUES (6, 'امکان حکاکی نام روی کیف وجود دارد؟', 'بله. حکاکی نام با مهر حروف برنجی روی پلاک چرمی انجام می‌شود و برای باکس هدیه آتلیه و توت سفر روشا امکان‌پذیر است. حکاکی حداکثر ۱۲ حرف و ۲ روز کاری زمان می‌برد.', 'سفارشی', 6, true);
INSERT INTO public.faqs VALUES (7, 'کیف چرم را چطور تمیز و نگهداری کنم؟', 'هر ۲ تا ۳ ماه با یک دستمال نرم و تمیز گردگیری کنید، سالی دو بار از واکس بی‌رنگ چرم استفاده کنید و کیف را دور از نور مستقیم خورشید و رادیاتور نگه دارید. برای لکه‌های چرب، فوراً از پودر تالک استفاده کنید و از دستمال مرطوب الکلی پرهیز کنید.', 'نگهداری', 7, true);
INSERT INTO public.faqs VALUES (8, 'سفارش عمده و همکاری با فروشگاه‌ها چطور است؟', 'برای سفارش‌های ۱۰ عدد به بالا، قیمت عمده و امکان حکاکی لوگوی فروشگاه وجود دارد. فرم فروش عمده را در صفحه «فروش عمده» تکمیل کنید؛ کارشناس ما حداکثر یک روز کاری تماس می‌گیرد.', 'عمده', 8, true);


