INSERT INTO public.products VALUES (1, 'kif-dasti-ariana', 'کیف دستی آریانا', 'دسته‌های بافته‌شده، ساختار سبک', 'آریانا یک کیف دستی چرم طبیعی با بدنه‌ی نرم و دسته‌های بافته‌شده است که برای استفاده‌ی روزمره و محیط کاری طراحی شده. آستر پارچه‌ای ضدآب و سه جیب داخلی، نظم وسایل شما را حفظ می‌کند و وزن کم آن باعث می‌شود تمام روز راحت باشد.', 'آریانا از یک پوست کامل گاوی در آتلیه‌ی تهران برش می‌خورد؛ هر کیف ۱۱ ساعت کار دست دارد و لبه‌ها با موم طبیعی پرداخت می‌شوند.', 3850000, 4400000, 'handbag', 'classic', '["/images/handbag-brown.jpg", "/images/handbag-white.jpg", "/images/woman-bag.jpg"]', '[{"hex": "#8a4b2a", "name": "کونьяک"}, {"hex": "#3a2418", "name": "اسپرسو"}, {"hex": "#d9c7ac", "name": "کرم شنی"}]', 'چرم طبیعی گاوی، آستر پارچه‌ای ضدآب', '۳۰ × ۲۲ × ۱۲ سانتی‌متر', 780, 12, 4.9, 128, 'پرفروش‌ترین', true, true, 'خرید کیف دستی چرم آریانا | کیف‌شاپ', 'کیف دستی آریانا، چرم طبیعی گاوی با دسته‌های بافته‌شده، سه جیب داخلی و گارانتی ۵ ساله. ساخت دست آتلیه کیف‌شاپ با ارسال رایگان و تعویض ۷ روزه.', '2026-10-29 16:28:34.883+00');
INSERT INTO public.products VALUES (2, 'kif-dooshi-niloofar', 'کیف دوشی نیلوفر', 'بند قابل تنظیم، فرم ارگونومیک', 'نیلوفر کیف دوشی مینیمال با بند تسمه‌ای قابل تنظیم است که روی شانه می‌نشیند و در پیاده‌روی‌های طولانی اذیت نمی‌کند. جیب پشتی مخفی برای کارت و گوشی، این کیف را به همراه همیشگی سفرهای شهری تبدیل کرده است.', 'الگوی نیلوفر از یک کیف آرشیوی دهه‌ی ۷۰ الهام گرفته و با یراق برنجی مات بازطراحی شده است.', 2480000, 2950000, 'crossbody', 'urban', '["/images/crossbody.jpg", "/images/purse-dark.jpg", "/images/woman-pose.jpg"]', '[{"hex": "#3a2418", "name": "اسپرسو"}, {"hex": "#a8563b", "name": "خاک رس"}, {"hex": "#1d1b18", "name": "مشکی مات"}]', 'چرم طبیعی گاوی، یراق برنجی مات', '۲۴ × ۱۸ × ۸ سانتی‌متر', 540, 21, 4.8, 94, 'انتخاب سردبیر', true, true, 'خرید کیف دوشی چرم نیلوفر | کیف‌شاپ', 'کیف دوشی نیلوفر با بند قابل تنظیم، جیب مخفی و چرم طبیعی. مناسب استفاده روزمره و سفر، با گارانتی ۵ ساله و ارسال رایگان از کیف‌شاپ.', '2026-10-28 16:28:34.883+00');
INSERT INTO public.products VALUES (3, 'tote-tarme', 'توت ترمه', 'جادار، سبک، برای هر روز', 'توت ترمه برای کسانی است که همه‌چیز را با خود می‌برند: لپ‌تاپ ۱۴ اینچ، دفتر و بطری آب. بدنه‌ی یک‌تکه چرم و دوخت تقویت‌شده‌ی دسته‌ها، تحمل وزن بالا را تضمین می‌کند و فرم کیف پس از ماه‌ها استفاده حفظ می‌شود.', 'ترمه محصول همکاری آتلیه با یک بافنده‌ی ترمه در یزد است؛ آستر داخلی از ترمه‌ی پنبه‌ای دست‌باف تهیه می‌شود.', 3290000, NULL, 'tote', 'classic', '["/images/tote-denim.jpg", "/images/tote-hand.jpg", "/images/woman-tote.jpg"]', '[{"hex": "#8a4b2a", "name": "کونьяک"}, {"hex": "#5d6350", "name": "زیتونی"}, {"hex": "#1d1b18", "name": "مشکی مات"}]', 'چرم طبیعی گاوی، آستر ترمه پنبه‌ای', '۳۸ × ۳۰ × ۱۴ سانتی‌متر', 920, 9, 4.9, 67, 'جدید', true, true, 'خرید توت چرم ترمه؛ کیف جادار زنانه | کیف‌شاپ', 'توت ترمه کیف چرم جادار با آستر ترمه دست‌باف، مناسب لپ‌تاپ ۱۴ اینچ و استفاده روزمره. ساخت دست، گارانتی ۵ ساله و ارسال رایگان.', '2026-10-27 16:28:34.883+00');
INSERT INTO public.products VALUES (4, 'kif-edari-pars', 'کیف اداری پارس', 'محفظه ضدضربه لپ‌تاپ ۱۵ اینچ', 'پارس یک کیف اداری چرم با ساختار نیمه‌سخت است که برای جلسه‌های کاری و سفرهای یک‌شبه طراحی شده. محفظه‌ی لپ‌تاپ با فوم ضدضربه، جیب اسناد A4، جیب کارت و بند شانه‌ی قابل جداشدن دارد.', 'پارس سه سال در دست تست میدانی بوده و آخرین بازبینی آن اضافه‌کردن آستر ضدآب و یراق ضدزنگ بوده است.', 4950000, 5600000, 'office', 'urban', '["/images/briefcase-black.jpg", "/images/briefcase-hand.jpg", "/images/man-office.jpg"]', '[{"hex": "#3a2418", "name": "اسپرسو"}, {"hex": "#1d1b18", "name": "مشکی مات"}, {"hex": "#8a4b2a", "name": "کونьяک"}]', 'چرم طبیعی گاوی دباغی گیاهی، یراق ضدزنگ', '۴۰ × ۳۰ × ۱۰ سانتی‌متر', 1250, 7, 4.9, 53, 'پیشنهاد ویژه', true, true, 'خرید کیف اداری چرم پارس؛ کیف لپ‌تاپ مردانه | کیف‌شاپ', 'کیف اداری پارس با محفظه ضدضربه لپ‌تاپ ۱۵ اینچ، چرم دباغی گیاهی و بند شانه قابل جدا شدن. مناسب جلسه کاری و سفر، گارانتی ۵ ساله.', '2026-10-26 16:28:34.883+00');
INSERT INTO public.products VALUES (5, 'kif-majlesi-shab', 'کیف مجلسی شب', 'کلاچ دست‌دوز با یراق طلایی', 'شب یک کلاچ کوچک و دقیق است؛ با درپوش مغناطیسی، جیب داخلی کارت و زنجیر قابل جداشدن. چرم مات و یراق طلایی آن با پارچه‌های ساتن و مخمل هماهنگ می‌شود.', 'هر کلاچ شب در یک شیفت کاری دوخته و پرداخت می‌شود؛ تعداد تولید ماهانه به ۳۰ عدد محدود است.', 2950000, 3400000, 'clutch', 'evening', '["/images/clutch.jpg", "/images/croc2.jpg", "/images/woman-pose.jpg"]', '[{"hex": "#1d1b18", "name": "مشکی مات"}, {"hex": "#c8a96a", "name": "طلایی"}, {"hex": "#a8563b", "name": "خاک رس"}]', 'چرم طبیعی بزی، یراق برنجی طلایی', '۲۶ × ۱۴ × ۶ سانتی‌متر', 390, 6, 4.7, 41, 'محدود', false, true, 'خرید کیف مجلسی شب؛ کلاچ چرم دست‌دوز | کیف‌شاپ', 'کلاچ مجلسی شب با چرم طبیعی، یراق طلایی و زنجیر قابل جدا شدن. تولید محدود آتلیه کیف‌شاپ با بسته‌بندی هدیه و ارسال رایگان.', '2026-10-25 16:28:34.883+00');
INSERT INTO public.products VALUES (6, 'kif-dasti-minoo', 'کیف دستی مینو', 'فرم کلاسیک با دسته‌ی کوتاه', 'مینو برای محیط اداری و قرارهای رسمی طراحی شده است. بدنه‌ی مستطیلی، سگک دستی و پایه‌های فلزی زیر کیف از نشستن بدنه روی میز جلوگیری می‌کند. جیب داخلی زیپ‌دار مناسب لپ‌تاپ ۱۳ اینچ است.', 'مینو نخستین الگوی آتلیه کیف‌شاپ است که از سال ۱۳۹۲ بدون تغییر در الگو تولید می‌شود.', 4150000, NULL, 'handbag', 'classic', '["/images/handbag-white.jpg", "/images/handbag-brown.jpg", "/images/shop-scene.jpg"]', '[{"hex": "#d9c7ac", "name": "کرم شنی"}, {"hex": "#8a4b2a", "name": "کونьяک"}, {"hex": "#3a2418", "name": "اسپرسو"}]', 'چرم طبیعی گاوی، آستر پارچه‌ای ضدآب', '۳۲ × ۲۴ × ۱۳ سانتی‌متر', 840, 11, 4.8, 88, NULL, true, true, 'خرید کیف دستی مینو؛ کیف چرم اداری زنانه | کیف‌شاپ', 'کیف دستی مینو با فرم کلاسیک، پایه فلزی و جیب زیپ‌دار لپ‌تاپ ۱۳ اینچ. چرم طبیعی و دوخت دست با گارانتی ۵ ساله در کیف‌شاپ.', '2026-10-24 16:28:34.883+00');
INSERT INTO public.products VALUES (7, 'kif-dasti-royal-croc', 'کیف دستی رویال کروک', 'چرم کروک‌امباس، تولید محدود', 'رویال با چرم کروک‌امباس و آستر جیر مصنوعی ساخته شده است. ساختار سخت کیف، فرم آن را در طول سال‌ها حفظ می‌کند و یراق طلایی، ظاهر مجلسی به آن داده است. در هر فصل تنها ۲۰ عدد تولید می‌شود.', 'پوست کروک‌امباس رویال از یک دباغی ایتالیایی تأمین می‌شود و پرداخت لبه‌ها با دست انجام می‌گیرد.', 6800000, 7600000, 'clutch', 'evening', '["/images/croc.jpg", "/images/croc2.jpg", "/images/woman-bag.jpg"]', '[{"hex": "#1d1b18", "name": "مشکی مات"}, {"hex": "#3a2418", "name": "اسپرسو"}, {"hex": "#c8a96a", "name": "طلایی"}]', 'چرم کروک‌امباس، آستر جیر', '۲۸ × ۱۹ × ۹ سانتی‌متر', 690, 4, 5, 26, 'لوکس', false, true, 'خرید کیف دستی رویال کروک؛ چرم کروک‌امباس | کیف‌شاپ', 'کیف دستی رویال با چرم کروک‌امباس، یراق طلایی و ساختار سخت. تولید محدود ۲۰ عدد در هر فصل، همراه با گارانتی ۵ ساله کیف‌شاپ.', '2026-10-23 16:28:34.883+00');
INSERT INTO public.products VALUES (8, 'box-hediye-atelier', 'باکس هدیه آتلیه', 'کیف + کیف پول + حکاکی نام', 'باکس هدیه آتلیه شامل یک کیف دستی کوچک، کیف پول جیبی و حکاکی نام روی پلاک چرمی است. بسته‌بندی در جعبه‌ی مقوایی مهر‌دار، کیسه‌ی پارچه‌ای و کارت دست‌نویس ارسال می‌شود.', 'برای سفارش‌های هدیه، نام گیرنده با مهر حروف برنجی روی چرم حک می‌شود؛ این کار در آتلیه و پیش از بسته‌بندی انجام می‌گیرد.', 3650000, 4200000, 'artisan', 'atelier', '["/images/box-bag.jpg", "/images/handbag-close.jpg", "/images/burnish.jpg"]', '[{"hex": "#8a4b2a", "name": "کونьяک"}, {"hex": "#5d6350", "name": "زیتونی"}, {"hex": "#1d1b18", "name": "مشکی مات"}]', 'چرم طبیعی گاوی، بسته‌بندی هدیه', 'جعبه ۳۴ × ۲۶ × ۱۴ سانتی‌متر', 1100, 15, 5, 39, 'هدیه', false, true, 'خرید باکس هدیه چرم با حکاکی نام | کیف‌شاپ', 'باکس هدیه آتلیه شامل کیف چرم، کیف پول و حکاکی نام؛ با بسته‌بندی مهر‌دار و کارت دست‌نویس. سفارش آنلاین با ارسال رایگان در کیف‌شاپ.', '2026-10-22 16:28:34.883+00');
INSERT INTO public.products VALUES (9, 'kif-dooshi-sahar', 'کیف دوشی سحر', 'جیب جلو، بند تسمه‌ای', 'سحر یک کراس‌بادی سبک با جیب جلوی زیپ‌دار است که برای حمل گوشی، کیف پول و کارت کافی است. فرم منحنی بدنه روی بدن می‌نشیند و در سفرهای شهری تکان نمی‌خورد.', 'سحر از باقی‌مانده‌ی پوست‌های آتلیه ساخته می‌شود؛ به همین دلیل هر رنگ محدود و تکرارنشدنی است.', 2180000, 2550000, 'crossbody', 'urban', '["/images/handbag-close.jpg", "/images/purse-dark.jpg", "/images/woman-pose.jpg"]', '[{"hex": "#8a4b2a", "name": "کونьяک"}, {"hex": "#1d1b18", "name": "مشکی مات"}, {"hex": "#5d6350", "name": "زیتونی"}]', 'چرم طبیعی گاوی، آستر پنبه‌ای', '۲۲ × ۱۶ × ۷ سانتی‌متر', 430, 18, 4.6, 74, 'ارزان‌ترین', false, true, 'خرید کیف دوشی کوچک سحر | کیف‌شاپ', 'کیف دوشی سبک سحر با جیب زیپ‌دار و بند تسمه‌ای قابل تنظیم؛ ساخته‌شده از چرم طبیعی با تولید محدود و گارانتی ۵ ساله.', '2026-10-21 16:28:34.883+00');
INSERT INTO public.products VALUES (10, 'tote-mahtab', 'توت دست‌ساز ماهتاب', 'دست‌دوز با مهر آتلیه', 'ماهتاب یک توت دست‌دوز است که درزهای آن با نخ موم‌اندود دوخته شده و هیچ چسب صنعتی در آن به کار نرفته است. جادار، سبک و مناسب استفاده‌ی روزمره؛ با گذشت زمان رنگ چرم عمیق‌تر می‌شود.', 'ماهتاب امضای آتلیه کیف‌شاپ است؛ هر عدد شماره‌ی سریال دارد و تعمیر آن تا ۱۰ سال انجام می‌شود.', 3490000, NULL, 'artisan', 'atelier', '["/images/tote-canvas.jpg", "/images/tote-hand.jpg", "/images/hand-stitch.jpg"]', '[{"hex": "#d9c7ac", "name": "کرم شنی"}, {"hex": "#a8563b", "name": "خاک رس"}, {"hex": "#3a2418", "name": "اسپرسو"}]', 'چرم طبیعی دباغی گیاهی، نخ موم‌اندود', '۳۶ × ۲۸ × ۱۲ سانتی‌متر', 860, 5, 5, 32, 'دست‌دوز', true, true, 'خرید توت دست‌ساز ماهتاب با دوخت دست | کیف‌شاپ', 'توت دست‌ساز ماهتاب با چرم دباغی گیاهی، دوخت دست و شماره سریال اختصاصی. تعمیر تا ۱۰ سال و گارانتی ۵ ساله کیف‌شاپ.', '2026-10-20 16:28:34.883+00');
INSERT INTO public.products VALUES (11, 'kif-edari-ronak', 'کیف اداری روناک', 'کیف لپ‌تاپ ۱۴ اینچ، فرم اسلیم', 'روناک برای کسانی است که کیف سبک می‌خواهند. بدنه‌ی اسلیم با محفظه‌ی لپ‌تاپ ۱۴ اینچ، جیب اسناد و دسته‌ی چرمی، همراهی مناسب برای رفت‌وآمد روزانه و جلسه‌های کوتاه است.', 'روناک از یک نمونه‌ی آرشیوی سفارشی برای معماران بازطراحی شد؛ جیب بیرونی برای دفتر A5 اضافه شده است.', 3890000, 4300000, 'office', 'urban', '["/images/briefcase-hand.jpg", "/images/briefcase-brown.jpg", "/images/man-office.jpg"]', '[{"hex": "#3a2418", "name": "اسپرسو"}, {"hex": "#5d6350", "name": "زیتونی"}, {"hex": "#1d1b18", "name": "مشکی مات"}]', 'چرم طبیعی گاوی، لایه محافظ لپ‌تاپ', '۳۷ × ۲۷ × ۶ سانتی‌متر', 940, 10, 4.7, 46, NULL, false, true, 'خرید کیف اداری اسلیم روناک؛ کیف لپ‌تاپ ۱۴ اینچ | کیف‌شاپ', 'کیف اداری روناک با بدنه اسلیم، محفظه لپ‌تاپ ۱۴ اینچ و چرم طبیعی. مناسب رفت‌وآمد روزانه و جلسه کاری، گارانتی ۵ ساله کیف‌شاپ.', '2026-10-19 16:28:34.883+00');
INSERT INTO public.products VALUES (12, 'tote-safar-rosha', 'توت سفر روشا', 'کیف سفر با بند شانه‌ای', 'روشا برای سفرهای دو‌روزه طراحی شده: بند شانه‌ای قابل جداشدن، جیب بیرونی برای پاسپورت و بدنه‌ای که زیر صندلی هواپیما جا می‌شود. چرم ضخیم و درزهای تقویت‌شده، وزن بالا را تحمل می‌کنند.', 'روشا در ۴ رنگ تولید می‌شود و امکان حکاکی حروف اول نام روی تسمه‌ی آن وجود دارد.', 4590000, NULL, 'tote', 'urban', '["/images/tote-magazine.jpg", "/images/tote-denim.jpg", "/images/woman-tote.jpg"]', '[{"hex": "#3a2418", "name": "اسپرسو"}, {"hex": "#8a4b2a", "name": "کونьяک"}, {"hex": "#d9c7ac", "name": "کرم شنی"}]', 'چرم طبیعی گاوی ضخیم', '۴۲ × ۳۲ × ۱۶ سانتی‌متر', 1180, 8, 4.8, 29, 'سفری', false, true, 'خرید توت سفر روشا؛ کیف چرم جادار | کیف‌شاپ', 'توت سفر روشا با بند شانه‌ای قابل جدا شدن، جیب بیرونی و چرم ضخیم؛ مناسب سفر دو‌روزه. امکان حکاکی نام با گارانتی ۵ ساله.', '2026-10-18 16:28:34.883+00');


